// crypto_kat_hw.c — on-silicon replay of the crypto MMIO KATs.
//
// crypto_kat_ops.h is generated by tools/vsim/crypto_kat.py --emit-c: the
// exact op list (expected values from Python hashlib / hmac / cryptography)
// that tb_crypto_mmio replays in simulation.  Then times AES-CTR per block
// (hardware counter vs the legacy software-counter ECB loop) and a SHA
// state save+restore.  Prints "=== ALL PASS ===" or a fail count.
// Build: tools/board/build.sh crypto_kat_hw -O2
#include <stdint.h>
#include <stdio.h>
#include "crypto_kat_ops.h"

#define DEV_BASE(d)  ((d) ? 0xF00B0000ul : 0xF00A0000ul)
#define REG(d, a)    (*(volatile uint64_t *)(DEV_BASE(d) + (a)))
#define CYCLES       (*(volatile uint64_t *)0xF00D0008ul)

static uint64_t scratch[64];

static int replay(void) {
    int fails = 0, mark = 0;
    for (unsigned i = 0; i < sizeof kat_ops / sizeof kat_ops[0]; i++) {
        const struct kat_op *o = &kat_ops[i];
        uint64_t r;
        unsigned n;
        switch (o->op) {
        case 1: REG(o->dev, o->addr) = o->data; break;
        case 2:
            r = REG(o->dev, o->addr);
            if ((r & o->mask) != o->data) {
                fails++;
                printf("FAIL test %d: dev %d @%03x read %016lx want %016lx\n", mark, o->dev,
                       o->addr, (unsigned long)r, (unsigned long)o->data);
            }
            break;
        case 3:
            for (n = 0; n < 100000; n++)
                if ((REG(o->dev, o->addr) & o->mask) == o->data) break;
            if (n == 100000) { fails++; printf("FAIL test %d: poll timeout @%03x\n", mark, o->addr); }
            break;
        case 5: scratch[o->data & 63] = REG(o->dev, o->addr); break;
        case 6: REG(o->dev, o->addr) = scratch[o->data & 63]; break;
        case 7: mark = (int)o->data; break;
        }
    }
    return fails;
}

#define NBLK 512
static uint64_t buf[2 * NBLK];

int main(void) {
    printf("crypto_kat_hw: %u ops\n", (unsigned)(sizeof kat_ops / sizeof kat_ops[0]));
    int fails = replay();
    printf("%s KAT replay (%d failures)\n", fails ? "FAIL" : "PASS", fails);

    // ---- timing: AES-128 CTR, NBLK blocks (key from the KAT run is loaded) ----
    for (int i = 0; i < 2 * NBLK; i++) buf[i] = 0x0123456789abcdefull * (i + 1);
    REG(0, 0xD0) = 1;                          // MODE = CTR
    REG(0, 0xC0) = 0; REG(0, 0xC8) = 0;
    uint64_t t0 = CYCLES;
    for (int b = 0; b < NBLK; b++) {
        REG(0, 0x40) = buf[2 * b];
        REG(0, 0x48) = buf[2 * b + 1];         // starts the block
        while (REG(0, 0x08) & 1) {}
        buf[2 * b]     = REG(0, 0x50);
        buf[2 * b + 1] = REG(0, 0x58);
    }
    uint64_t t_hw = CYCLES - t0;
    uint64_t c1 = REG(0, 0xC8);
    REG(0, 0xD0) = 0;

    // legacy: software counter + ECB GO + software XOR
    uint64_t ctr_lo = 0, ctr_hi = 0;
    t0 = CYCLES;
    for (int b = 0; b < NBLK; b++) {
        REG(0, 0x40) = ctr_lo;
        REG(0, 0x48) = ctr_hi;
        REG(0, 0x00) = 3;                      // GO | ENC
        while (REG(0, 0x08) & 1) {}
        buf[2 * b]     ^= REG(0, 0x50);
        buf[2 * b + 1] ^= REG(0, 0x58);
        uint64_t be = __builtin_bswap64(ctr_hi) + 1;   // big-endian low half
        ctr_hi = __builtin_bswap64(be);
        if (be == 0) ctr_lo = __builtin_bswap64(__builtin_bswap64(ctr_lo) + 1);
    }
    uint64_t t_sw = CYCLES - t0;
    // CTR1 after NBLK blocks from 0: counter LSBs = NBLK, big-endian in bytes 14..15
    int ctr_ok = (c1 == ((uint64_t)__builtin_bswap16(NBLK) << 48));
    if (!ctr_ok) { fails++; printf("FAIL CTR1 after %d blocks = %016lx\n", NBLK, (unsigned long)c1); }
    printf("aes-ctr hw counter : %lu cycles/block (%lu KB/s @100MHz)\n",
           (unsigned long)(t_hw / NBLK), (unsigned long)(100000000ull * 16 * NBLK / t_hw / 1024));
    printf("aes-ctr sw counter : %lu cycles/block (%lu KB/s @100MHz)\n",
           (unsigned long)(t_sw / NBLK), (unsigned long)(100000000ull * 16 * NBLK / t_sw / 1024));

    // ---- timing: fused AES-GCM encrypt, NBLK blocks (H/tag state is whatever
    //      the KAT left; only the cycle count matters here) ----
    if (REG(0, 0xF8) & 4) {
        REG(0, 0x80) = 2;                       // GCM tag reset
        REG(0, 0xD0) = 1 | 2 | 8;               // CTR | GCM_FUSE | INC32
        t0 = CYCLES;
        for (int b = 0; b < NBLK; b++) {
            REG(0, 0x40) = buf[2 * b];
            REG(0, 0x48) = buf[2 * b + 1];
            while (REG(0, 0x08) & 1) {}
            buf[2 * b]     = REG(0, 0x50);
            buf[2 * b + 1] = REG(0, 0x58);
        }
        while (REG(0, 0x88) & 1) {}
        uint64_t t_gcm = CYCLES - t0;
        REG(0, 0xD0) = 0;
        printf("aes-gcm fused      : %lu cycles/block (%lu KB/s @100MHz)\n",
               (unsigned long)(t_gcm / NBLK), (unsigned long)(100000000ull * 16 * NBLK / t_gcm / 1024));
    }

    // ---- timing: SHA save (4 reads) + restore (4 writes + RESTORE + wait) ----
    uint64_t h[4];
    t0 = CYCLES;
    for (int k = 0; k < 64; k++) {
        for (int i = 0; i < 4; i++) h[i] = REG(1, 0x50 + 8 * i);
        for (int i = 0; i < 4; i++) REG(1, 0xC0 + 8 * i) = h[i];
        REG(1, 0x00) = 4;
        while (REG(1, 0x08) & 1) {}
    }
    printf("sha save+restore   : %lu cycles\n", (unsigned long)((CYCLES - t0) / 64));

    if (fails) printf("=== %d FAIL ===\n", fails);
    else       printf("=== ALL PASS ===\n");
    return 0;
}
